  +    for (const m of clause.matchAll(NO_NEED)) refs.push(m[0]);
  +    for (const m of clause.matchAll(NO_LONGER)) refs.push(m[0]);
  +    for (const ref of refs) for (const n of ref.match(/\d+/g) ?? []) found.add(`R${Number(n)}`);
