/** Ends waiting /compact requests that will not run. */
private dropPendingCompactions(reason: string): void {
  for (const p of this.pendingCompactions) this.compactionResult(p.ids, false, `/compact was not run: ${reason}.`);
  this.pendingCompactions = [];
}

/** Runs one turn or command as the session's only activity. Busy is reported before `body` starts. */
private runJob(id: string, spec: SlashSpec | undefined, body: (signal: AbortSignal) => Promise<void>): void {
  const abort = new AbortController();
  this.turnAbort = abort;
  this.activeSpec = spec;
  let settle!: () => void;
  this.activeTurn = new Promise<void>((resolve) => {
    settle = resolve;
  });
  this.emitSessionState();
  void body(abort.signal)
    .catch((err) => this.emit({ type: "error", id, code: "INTERNAL", message: errorText(err) }))
    .finally(() => {
      this.activeTurn = undefined;
      this.turnAbort = undefined;
      this.activeSpec = undefined;
      // Queued /compact runs before anything else starts, without an idle state in between.
      if (this.pendingCompactions.length && !this.shutdownPromise) {
        const pending = this.pendingCompactions;
        this.pendingCompactions = [];
        settle();
        this.runJob(pending[0].ids[0], findSlash("compact"), async (signal) => {
          for (const p of pending) {
            const result = await this.app.getAgent().compactNow(p.llm, signal);
            this.compactionResult(p.ids, result.ok, result.message);
          }
        });
        return;
      }
      if (this.pendingCompactions.length) this.dropPendingCompactions("the sidecar is shutting down");
      // Deferred steering starts its turn without an idle state in between, so nothing can slip into the gap.
      if (this.followUps.length && !this.shutdownPromise) {
        settle();
        this.startFollowUp();
        return;
      }
      this.emitSessionState();
      settle();
    });
}

private submit(id: string, text: string): void {
  if (this.rejectBusy(id)) return;
  this.runJob(id, undefined, (signal) =>
    this.gatedTurn(id, text, signal, {

      // The tool that was running when the operator asked to stop has now settled.
      if (signal.aborted && modelStop === "NONE") {
        markInterrupted(turn.toolInFlightAtCancel ? "tool_settling" : "tool_dispatch", turn.toolInFlightAtCancel ? { outstandingTool: turn.toolInFlightAtCancel, outstandingToolSettled: true } : {});
        break;
      }
      // Steering that arrived while the agent was finishing is applied rather than ending on a stale objective.
      if (modelStop === "TASK_COMPLETED_TOOL" && this.hasQueuedSteering()) {
        modelStop = "NONE";
        finalOutputComplete = false;
      }

      endStep();
    }
    turn.closing = true;
    if (this.objective) settleSteeringConflicts(this.objective);
    // Queued /compact: run now that the last step has settled, or cancelled with the turn.
    if (this.compactionQueue.length) {
      try {
        await this.drainCompactionQueue(currentStep, undefined, interruption ? "the turn was cancelled" : persistenceFailure ? "the turn stopped on a persistence failure" : undefined, true);
      } catch (err) {
        if (!(err instanceof CompactionCommitError)) throw err;
        persistenceFailure ??= err.outcome.message;
      }
    }
    if (this.hasQueuedSteering()) {
    if (this.flightRecorder) {
      this.flightRecorder.recordSessionEnd(
        `${summarizeTurn(result).heading}: ${summarizeTurn(result).line}`,
        result.execution === "COMPLETED" && (result.outcome === "VERIFIED" || result.outcome === "NOT_REQUIRED"),
        this.totalTokens
      );
    }
    this.ui.turnSummary(result, this.completionSummary);
    return result;
  } catch (err: any) {
    turn.closing = true;
    if (this.objective) settleSteeringConflicts(this.objective);
    if (this.compactionQueue.length) {
      try {
        await this.drainCompactionQueue(currentStep, undefined, "the turn failed unexpectedly");
      } catch {}
    }
    if (this.hasQueuedSteering()) {
      this.cancelQueuedSteering(
        `the turn failed unexpectedly (${redactSecrets(String(err?.message ?? err)).slice(0, 200)}) before it could be applied`
      );

